    fn test_mcs2i_setter_wrong_inputs() {
        let source = "\
classdef MyClass
    properties
        Value
    end

    methods
        function set.Value(obj)
            obj.Value = 0;
        end
    end
end
";
        let diags = check_source(source, "MyClass.m");
