    #[test]
    fn test_mcg1i_getter_wrong_inputs() {
        let source = "\
classdef MyClass
    properties
        Value
    end

    methods
        function val = get.Value(obj, extra)
            val = obj.Value;
        end
    end
end
";
        let diags = check_source(source, "MyClass.m");
        let mcg1i = filter_by_id(&diags, "MCG1I");
        assert!(
            !mcg1i.is_empty(),
            "MCG1I should fire when getter has wrong number of inputs"
        );
