    fn test_mcsgp_setter_invalid_property() {
        let source = "\
classdef MyClass
    properties
        Value
    end

    methods
        function set.NonExistent(obj, val)
            obj.NonExistent = val;
        end
    end
end
";
        let diags = check_source(source, "MyClass.m");
