    let constant_props: Vec<String> = class.properties_blocks.iter()
        .filter(|pb| pb.attributes.iter().any(|a| a.name == "Constant" && !a.negated))
        .flat_map(|pb| pb.properties.iter().map(|p| p.name.clone()))
        .collect();
    if constant_props.is_empty() {
        return;
    }
    Self::walk_constant_assignments(func_node, &constant_props, &method_name, is_constructor, source, diagnostics);
}

fn walk_constant_assignments(
    node: tree_sitter::Node,
    constant_props: &[String],
    method_name: &str,
    is_constructor: bool,
    source: &str,
    diagnostics: &mut Vec<Diagnostic>,
