fn check_superclass_rules(
    &self,
    class: &ClassMeta,
    ctx: &FileContext,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let source = ctx.source;
    let root = ctx.tree.root_node();
    let functions = self.collect_function_definitions(root, source);

    for (func_node, mname) in &functions {
        let outputs = function_output_names(*func_node, source);
        let first_output = outputs.first().cloned();
        let is_constructor = mname == &class.name;
        let calls = self.collect_superclass_calls(*func_node, source);
        if calls.is_empty() {
            continue;
        }
        let mut constructor_calls_seen = 0usize;
        for (call_node, caller, super_name) in calls {
            if is_constructor && Some(caller.as_str()) == first_output.as_deref() {
                // A superclass constructor call.
                if constructor_calls_seen == 0 {
                    constructor_calls_seen += 1;
                    // MCCBU
                    if self.is_check_enabled("MCCBU") {
                        self.check_super_after_object_use(*func_node, call_node, &caller, source, diagnostics);
                    }
                } else {
                    if self.is_check_enabled("MCCMC") {
                        push MCCMC at call_node
                    }
                }
                // MCCBS
                if self.is_check_enabled("MCCBS")
                    && !class.superclasses.iter().any(|s| s == &super_name)
                {
                    push MCCBS with super_name
                }
                // MCSCT
                if self.is_check_enabled("MCSCT")
                    && self.super_call_is_conditional_or_expression(call_node)
                {
                    push MCSCT
                }
                // Assignment checks: MCSCF / MCSMO
                if let Some(lhs) = call_node.parent().and_then(|p| if p.kind() == "assignment" { Some(p.child_by_field_name("left")) } else { None }).flatten() {
                    if lhs.kind() == "multioutput_variable" {
                        if self.is_check_enabled("MCSMO") { push MCSMO }
                    } else if lhs.kind() == "identifier" {
                        let lhs_text = node_text(lhs, source);
                        if lhs_text != first_output.as_deref().unwrap_or("") {
                            if self.is_check_enabled("MCSCF") { push MCSCF }
                        }
                    }
                } else {
                    // not in an assignment → MCSCF (must be assigned)
                    if self.is_check_enabled("MCSCF") { push MCSCF }
                }
            } else if is_constructor {
                // caller != first output
                if outputs.iter().any(|o| o == &caller) {
                    // caller is an output but not the first → MCSCO
                    if self.is_check_enabled("MCSCO") {
                        push MCSCO
                    }
                } else if caller != *mname {
                    if self.is_check_enabled("MCSCM") {
                        push MCSCM
                    }
                }
            } else {
                // non-constructor method
                if Some(caller.as_str()) == first_output.as_deref() {
                    if self.is_check_enabled("MCSCC") {
                        push MCSCC
                    }
                } else if caller != *mname {
                    if self.is_check_enabled("MCSCM") {
                        push MCSCM
                    }
                }
            }
        }
    }
}
