fn super_call_is_conditional_or_expression(&self, call_node: tree_sitter::Node) -> bool {
    // part of another expression: direct parent is not an assignment whose RHS is the call
    let parent = call_node.parent();
    let part_of_expr = match parent {
        Some(p) if p.kind() == "assignment" => {
            p.child_by_field_name("right").map(|r| r.id() != call_node.id()).unwrap_or(true)
        }
        Some(p) => p.kind() != "assignment",
        None => true,
    };
    if part_of_expr {
        return true;
    }
    // conditionalized: any ancestor between the assignment and function_definition is a control-flow node
    let mut cur = call_node;
    while let Some(p) = cur.parent() {
        if p.kind() == "function_definition" {
            break;
        }
        if matches!(p.kind(),
            "if_statement" | "for_statement" | "while_statement" | "switch_statement"
            | "try_statement" | "spmd_statement"
        ) {
            return true;
        }
        cur = p;
    }
    false
}
