+                rule_id: "MCSWA",
+                message: "A sealed class cannot specify allowed subclasses".to_string(),
+                severity: Severity::Error,
+                byte_range: class.byte_range.clone(),
+                line: class.line,
+                column: 1,
+                fix: None,
+            });
+        }
+    }
